# Re-measure a few representative lots and a certified standard to assess instrument noise/bias
materials = ["N0026", "N0038", "N0048", "estandar:3", "blanco", "solvente"]
for mat in materials:
    m = env.measure(mat, reps=4)
    print(f"\nmaterial={mat} shape={m.shape}")
    print(m.head())
    if "y" in m.columns:
        print(m.groupby("material")["y"].agg(["mean", "std", "min", "max"]))
    if "nominal" in m.columns:
        print("nominal values:", m["nominal"].dropna().unique())
